import javax.tools.*;import com.sun.source.util.JavacTask;import java.nio.file.*;import java.util.*;
public class ParseJava {public static void main(String[] args)throws Exception{List<java.io.File> files=new ArrayList<>();try(java.util.stream.Stream<Path> walk=Files.walk(Paths.get(args[0]))){walk.filter(p->p.toString().endsWith(".java")).forEach(p->files.add(p.toFile()));}DiagnosticCollector<JavaFileObject> diagnostics=new DiagnosticCollector<>();JavaCompiler compiler=ToolProvider.getSystemJavaCompiler();try(StandardJavaFileManager fm=compiler.getStandardFileManager(diagnostics,null,null)){JavacTask task=(JavacTask)compiler.getTask(null,fm,diagnostics,Arrays.asList("-proc:none","--release","17"),null,fm.getJavaFileObjectsFromFiles(files));task.parse();for(Diagnostic<?> d:diagnostics.getDiagnostics())System.out.println(d);long errors=diagnostics.getDiagnostics().stream().filter(d->d.getKind()==Diagnostic.Kind.ERROR).count();if(errors>0)throw new AssertionError("Parse errors "+errors);System.out.println("JAVA PARSE PASS "+files.size()+" files (syntax only, Android SDK type resolution not run)");}}}
